const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const LAN = 'http://192.168.3.201', PVE = 'https://192.168.3.200:8006';
const helpers = this.helpers;
const s = $getWorkflowStaticData('global');
const say = (text) => helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/sendMessage`, body: { chat_id: CHAT, text, disable_web_page_preview: true }, json: true, timeout: 15000 });
const get = (url, opts = {}) => helpers.httpRequest({ url, json: true, timeout: 20000, ...opts });
const safe = async (fn) => { try { return await fn(); } catch (e) { return null; } };
const lagosNow = () => new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const prom = async (expr) => { const r = await get(`${LAN}:9090/api/v1/query`, { qs: { query: expr } }); const v = r?.data?.result?.[0]?.value?.[1]; return v === undefined ? null : Number(v); };
const pveGet = (path) => get(`${PVE}/api2/json${path}`, { headers: { Authorization: `PVEAPIToken=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_ID}=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_SECRET}` }, skipSslCertificateValidation: true }).then(r => r.data);
const ghHeaders = (extra = {}) => ({ Authorization: `Bearer ${$env.HOMELAB_GITHUB_TOKEN || ''}`, Accept: 'application/vnd.github+json', 'User-Agent': 'homelab-n8n', ...extra });
const gh = (path, opts = {}) => { const { headers, ...rest } = opts; return helpers.httpRequest({ url: `https://api.github.com${path}`, json: true, timeout: 20000, headers: ghHeaders(headers), ...rest }); };
const REPO = $env.HOMELAB_GITHUB_REPO || 'theOGpython/homelab';

// Morning briefing. Input items come from the "Today's events" Google Calendar node (may be empty).
const SITE = { lat: 6.50, lon: 3.35 };
const WMO = { 0: 'clear ☀️', 1: 'mostly clear 🌤', 2: 'partly cloudy ⛅', 3: 'cloudy ☁️', 45: 'foggy 🌫', 48: 'foggy 🌫', 51: 'light drizzle 🌦', 53: 'drizzle 🌦', 55: 'drizzle 🌦',
  61: 'light rain 🌧', 63: 'rain 🌧', 65: 'heavy rain 🌧', 80: 'showers 🌦', 81: 'showers 🌧', 82: 'heavy showers ⛈', 95: 'thunderstorms ⛈', 96: 'thunderstorms ⛈', 99: 'thunderstorms ⛈' };
const t = lagosNow(), today = ymd(t);
const events = $input.all().map(i => i.json).filter(e => e && (e.summary || e.start));

const [wx, power, internet, tv, pool] = await Promise.all([
  safe(() => get('https://api.open-meteo.com/v1/forecast', { qs: { latitude: SITE.lat, longitude: SITE.lon, timezone: 'Africa/Lagos', forecast_days: 1,
    daily: 'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max' } })),
  safe(() => Promise.all([prom('felicity_battery_soc_percent'), prom('felicity_grid_present'), prom('solar_forecast_today_kwh'),
    prom('avg_over_time(felicity_grid_present[12h]) * 12'), prom('resets(felicity_grid_present[12h])')])),
  safe(() => prom('odu_month_download_bytes + odu_month_upload_bytes')),
  safe(() => get(`${LAN}:8989/api/v3/calendar`, { headers: { 'X-Api-Key': $env.HOMEPAGE_VAR_SONARR_KEY || '' },
    qs: { start: `${today}T00:00:00+01:00`, end: `${today}T23:59:59+01:00`, includeSeries: true } })),
  safe(() => pveGet('/nodes/pve/storage/local-lvm/status')),
]);

const L = [`🌅 Good morning! ${t.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' })}`];
if (wx?.daily) {
  const w = wx.daily;
  L.push(`🌡 ${Math.round(w.temperature_2m_min[0])}–${Math.round(w.temperature_2m_max[0])}°C, ${WMO[w.weather_code[0]] || 'mixed'}` +
    (w.precipitation_probability_max[0] >= 30 ? `, ${w.precipitation_probability_max[0]}% chance of rain` : ''));
}
if (power) {
  const [soc, grid, fc, gridH, cuts] = power;
  if (fc !== null) L.push(`☀️ Solar forecast: ${fc.toFixed(1)} kWh` + (fc < 4 ? ' (a dull day: go easy on power)' : fc > 8 ? ' (a bright day)' : ''));
  if (soc !== null) L.push(`🔋 Battery ${Math.round(soc)}% · ${grid >= 1 ? '⚡ grid ON' : '⚠️ grid OFF'}`);
  if (gridH !== null) L.push(`🌙 Last 12 h: grid for ${hm(gridH)}` + (cuts ? ` (${cuts} power cut${cuts === 1 ? '' : 's'})` : ''));
}
if (internet !== null) L.push(`📶 Data used this billing period: ${(internet / 1e9).toFixed(0)} GB`);

L.push('');
if (events.length) {
  L.push('📅 Today:');
  for (const e of events.slice(0, 8)) {
    const st = e.start?.dateTime ? new Date(e.start.dateTime).toLocaleTimeString('en-GB', { timeZone: 'Africa/Lagos', hour: '2-digit', minute: '2-digit' }) : 'All day';
    L.push(`   ${st}  ${e.summary || '(no title)'}`);
  }
} else L.push('📅 Nothing on the calendar today.');

if (tv?.length) L.push(`📺 New tonight: ${[...new Set(tv.map(x => `${x.series?.title} S${pad(x.seasonNumber)}E${pad(x.episodeNumber)}`))].slice(0, 4).join(', ')}`);
if (pool) { const pct = Math.round(pool.used / pool.total * 100); if (pct >= 80) L.push(`💾 Storage pool at ${pct}% ⚠️ consider deleting watched media (/delete).`); }

await say(L.join('\n'));
return [{ json: { sent: true } }];
